export type TimeRange = readonly [start: number, end: number];

export interface Booking {
  readonly id: number;
  lab: string;
  range: TimeRange;
  seats: number;
}

export function label(b: Booking): string {
  return b.lab + ' · ' + b.seats + ' seats';
}

// Booking as the calendar export sees it (added later by another teammate).
export interface Booking {
  title: string;
  allDay: boolean;
}

import { toEvent } from '../src/booking.ts';
import type { Booking, CalendarEvent } from '../src/booking.ts';

const b: Booking = { id: 1, lab: 'BE-201', range: [480, 600], seats: 30 };
const e: CalendarEvent = toEvent(b);
export { e };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { label, toEvent } from '../src/booking.ts';

test('label', () => assert.equal(label({ id: 1, lab: 'BE-201', range: [480, 600], seats: 30 }), 'BE-201 · 30 seats'));
test('toEvent', () => assert.deepEqual(toEvent({ id: 1, lab: 'AL-301', range: [600, 720], seats: 12 }), { title: 'AL-301 · 12 seats', allDay: false, range: [600, 720] }));

