export type TimeRange = readonly [start: number, end: number];

export interface Booking {
  readonly id: number;
  lab: string;
  range: TimeRange;
  seats: number;
}

export function label(b: Booking): string {
  return b.lab + ' · ' + b.seats + ' seats';
}

// The calendar's view is a different shape, so it has its own name — no second "interface Booking".
export interface CalendarEvent {
  title: string;
  allDay: boolean;
  range: TimeRange;
}

export function toEvent(b: Booking): CalendarEvent {
  return { title: label(b), allDay: false, range: b.range };
}

