type Pending = { status: 'PENDING' };
type Confirmed = { status: 'CONFIRMED'; approvedBy: string };
export type BookingState = Pending | Confirmed;

// Every state, plus the lab it belongs to.
export interface StateWithLab extends BookingState {
  lab: string;
}

export function describe(s: StateWithLab): string {
  return s.lab + ': ' + s.status;
}

import type { StateWithLab } from '../src/state.ts';

const a: StateWithLab = { status: 'PENDING', lab: 'BE-201' };
const b: StateWithLab = { status: 'CONFIRMED', approvedBy: 'binh.tt', lab: 'AL-301' };
export { a, b };

import type { StateWithLab } from '../src/state.ts';

const noLab: StateWithLab = { status: 'PENDING' }; // expect TS2322
const done: StateWithLab = { status: 'DONE', lab: 'BE-201' }; // expect TS2322
export { noLab, done };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { describe } from '../src/state.ts';

test('describe', () => assert.equal(describe({ status: 'CONFIRMED', approvedBy: 'binh.tt', lab: 'AL-301' }), 'AL-301: CONFIRMED'));

