import type { Handler } from './lib.ts';

// The login middleware stores the user id on the request. Make the "library" type know about it.

export const whoAmI: Handler = (req) => (req.userId === undefined ? 'guest' : 'user ' + req.userId);

// A tiny "library" (given — do not edit): a request object and a handler type.
export interface Req {
  url: string;
}
export type Handler = (req: Req) => string;

export function handle(h: Handler, req: Req): string {
  return h(req);
}

import { handle } from '../src/lib.ts';
import type { Req } from '../src/lib.ts';
import { whoAmI } from '../src/auth.ts';

const guest: Req = { url: '/me' };
const logged: Req = { url: '/me', userId: 7 };
console.log(handle(whoAmI, guest), handle(whoAmI, logged));

import type { Req } from '../src/lib.ts';
import '../src/auth.ts';

declare const req: Req;
const id: number = req.userId; // expect TS2322
const text: Req = { url: '/me', userId: '7' }; // expect TS2322
export { id, text };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { handle } from '../src/lib.ts';
import { whoAmI } from '../src/auth.ts';

test('guest', () => assert.equal(handle(whoAmI, { url: '/me' }), 'guest'));
test('logged in', () => assert.equal(handle(whoAmI, { url: '/me', userId: 7 }), 'user 7'));

